package org.duckdns.hjow.swingwebpanel.tls13.crypto;

import java.math.BigInteger;
import java.util.List;
import org.duckdns.hjow.swingwebpanel.testing.Check;
import org.duckdns.hjow.swingwebpanel.tls13.Hex;
import org.duckdns.hjow.swingwebpanel.tls13.Vectors;

/**
 * Cross-check of the cryptographic primitives against an independent implementation (plan item P32-03): the resource
 * <code>jca-vectors.txt</code> was generated by <code>tools/tlsvectors</code> with the standard providers of a newer JRE (the version
 * is in the header of the file). Covered: AES-GCM and ChaCha20-Poly1305 for many lengths, X25519, ECDH and ECDSA on P-256, P-384 and
 * P-521, RSA PKCS #1 v1.5 and RSA-PSS for several modulus and salt lengths.
 * <p>
 * 암호 기본 요소를 독립 구현과 대조한다(계획 P32-03): 자료 <code>jca-vectors.txt</code> 는 <code>tools/tlsvectors</code> 가 더 새 JRE 의 표준
 * 공급자로 만들었다(판은 파일 머리에 있다). 대상: 여러 길이의 AES-GCM 과 ChaCha20-Poly1305, X25519, P-256·P-384·P-521 의 ECDH 와 ECDSA,
 * 여러 법 길이와 salt 길이의 RSA PKCS #1 v1.5 와 RSA-PSS.
 */
public class JcaCrossCheckTest {

    /** The generated vectors. / 생성한 벡터. */
    private static final Vectors VECTORS = Vectors.load("/jca-vectors.txt");

    /**
     * Creates the suite (required by the runner).
     * <p>
     * 스위트를 만든다(실행기가 필요로 함).
     */
    public JcaCrossCheckTest() {
    }

    /**
     * Decodes a hexadecimal value of the file; a minus sign is the empty value.
     * <p>
     * 파일의 16진수 값을 읽는다. 빼기 기호는 빈 값이다.
     *
     * @param word the word / 낱말
     * @return the bytes / 바이트
     */
    private static byte[] bytes(String word) {
        return "-".equals(word) ? new byte[0] : Hex.decode(word);
    }

    /**
     * Returns the hash of a name used in the file.
     * <p>
     * 파일에서 쓰는 이름의 해시를 반환한다.
     *
     * @param name <code>SHA-256</code>, <code>SHA-384</code> or <code>SHA-512</code> / 해시 이름
     * @return the hash / 해시
     */
    private static HashAlg hash(String name) {
        return "SHA-256".equals(name) ? HashAlg.SHA256 : "SHA-384".equals(name) ? HashAlg.SHA384 : HashAlg.SHA512;
    }

    /**
     * Returns the curve of a name used in the file.
     * <p>
     * 파일에서 쓰는 이름의 곡선을 반환한다.
     *
     * @param name <code>P-256</code>, <code>P-384</code> or <code>P-521</code> / 곡선 이름
     * @return the curve / 곡선
     */
    private static EcCurve curve(String name) {
        return "P-256".equals(name) ? EcCurve.P256 : "P-384".equals(name) ? EcCurve.P384 : EcCurve.P521;
    }

    /**
     * Seals every AEAD vector and compares with the reference, then opens the reference.
     * <p>
     * AEAD 벡터마다 봉인한 결과를 기준과 비교하고 기준을 연다.
     *
     * @param kind <code>gcm</code> or <code>chacha</code> / 종류
     * @return the number of vectors / 벡터 수
     */
    private static int aead(String kind) {
        List<String[]> lines = VECTORS.all(kind);
        // 벡터마다 봉인과 개봉을 확인한다.
        for (int i = 0; i < lines.size(); i++) {
            String[] w = lines.get(i);
            byte[] key = bytes(w[1]);
            Aead aead = "gcm".equals(kind) ? (Aead) new AesGcm(key) : (Aead) new ChaCha20Poly1305(key);
            byte[] nonce = bytes(w[2]);
            byte[] aad = bytes(w[3]);
            byte[] plain = bytes(w[4]);
            byte[] sealed = bytes(w[5]);
            byte[] out = new byte[plain.length + 16];
            aead.seal(nonce, aad, plain, 0, plain.length, out, 0);
            String what = kind + " vector " + i + " (key " + key.length + ", plaintext " + plain.length + ", aad " + aad.length + ")";
            Check.equal(Hex.encode(sealed), Hex.encode(out), what + ": sealed");
            byte[] back = new byte[plain.length];
            Check.isTrue(aead.open(nonce, aad, sealed, 0, sealed.length, back, 0), what + ": the reference opens");
            Check.equal(Hex.encode(plain), Hex.encode(back), what + ": opened");
        }
        return lines.size();
    }

    /**
     * AES-128-GCM and AES-256-GCM agree with the reference for plaintexts from 0 to 1000 bytes.
     * <p>
     * AES-128-GCM 과 AES-256-GCM 이 0~1000바이트 평문에서 기준과 일치한다.
     */
    public void testAesGcm() {
        Check.isTrue(aead("gcm") >= 30, "enough AES-GCM vectors");
    }

    /**
     * ChaCha20-Poly1305 agrees with the reference for plaintexts from 0 to 1000 bytes.
     * <p>
     * ChaCha20-Poly1305 가 0~1000바이트 평문에서 기준과 일치한다.
     */
    public void testChaCha20Poly1305() {
        Check.isTrue(aead("chacha") >= 15, "enough ChaCha20-Poly1305 vectors");
    }

    /**
     * X25519 public keys and shared secrets agree with the reference.
     * <p>
     * X25519 공개 키와 공유 비밀이 기준과 일치한다.
     *
     * @throws Exception never for these inputs / 이 입력에서는 발생하지 않는다
     */
    public void testX25519() throws Exception {
        List<String[]> lines = VECTORS.all("x25519");
        Check.isTrue(lines.size() >= 10, "enough X25519 vectors");
        // 벡터마다 공개 키와 공유 비밀을 확인한다.
        for (int i = 0; i < lines.size(); i++) {
            String[] w = lines.get(i);
            Check.equal(w[2], Hex.encode(X25519.publicKey(bytes(w[1]))), "public key " + i);
            Check.equal(w[4], Hex.encode(X25519.sharedSecret(bytes(w[1]), bytes(w[3]))), "shared secret " + i);
        }
    }

    /**
     * ECDH shared secrets on the three curves agree with the reference.
     * <p>
     * 세 곡선의 ECDH 공유 비밀이 기준과 일치한다.
     *
     * @throws Exception never for these inputs / 이 입력에서는 발생하지 않는다
     */
    public void testEcdh() throws Exception {
        List<String[]> lines = VECTORS.all("ecdh");
        Check.isTrue(lines.size() >= 18, "enough ECDH vectors");
        // 벡터마다 공유 비밀을 확인한다.
        for (int i = 0; i < lines.size(); i++) {
            String[] w = lines.get(i);
            EcCurve c = curve(w[1]);
            Ecdh dh = new Ecdh(c, new BigInteger(w[2], 16));
            byte[] peer = c.encodePoint(new BigInteger[] { new BigInteger(w[3], 16), new BigInteger(w[4], 16) });
            Check.equal(w[5], Hex.encode(dh.sharedSecret(peer)), w[1] + " shared secret " + i);
        }
    }

    /**
     * ECDSA signatures made by the reference verify, and a changed message does not.
     * <p>
     * 기준이 만든 ECDSA 서명이 검증되고, 메시지를 바꾸면 검증되지 않는다.
     */
    public void testEcdsa() {
        List<String[]> lines = VECTORS.all("ecdsa");
        Check.isTrue(lines.size() >= 36, "enough ECDSA vectors");
        // 벡터마다 서명을 검증한다.
        for (int i = 0; i < lines.size(); i++) {
            String[] w = lines.get(i);
            EcCurve c = curve(w[1]);
            HashAlg h = hash(w[2]);
            BigInteger[] q = { new BigInteger(w[3], 16), new BigInteger(w[4], 16) };
            byte[] message = bytes(w[5]);
            BigInteger r = new BigInteger(w[6], 16);
            BigInteger s = new BigInteger(w[7], 16);
            String what = w[1] + " with " + w[2] + ", vector " + i;
            Check.isTrue(Ecdsa.verify(c, q, h.digest(message), r, s), what + ": valid");
            Check.isFalse(Ecdsa.verify(c, q, h.digest(message, new byte[] { 1 }), r, s), what + ": another message");
        }
    }

    /**
     * RSA PKCS #1 v1.5 signatures made by the reference verify for 2048, 2049, 3072 and 4096 bit moduli; changes do not.
     * <p>
     * 기준이 만든 RSA PKCS #1 v1.5 서명이 2048, 2049, 3072, 4096비트 법에서 검증되고, 바꾸면 검증되지 않는다.
     */
    public void testRsaPkcs1() {
        List<String[]> lines = VECTORS.all("rsa-pkcs1");
        Check.isTrue(lines.size() >= 12, "enough PKCS #1 vectors");
        // 벡터마다 서명을 검증한다.
        for (int i = 0; i < lines.size(); i++) {
            String[] w = lines.get(i);
            HashAlg h = hash(w[1]);
            BigInteger n = new BigInteger(w[2], 16);
            BigInteger e = new BigInteger(w[3], 16);
            byte[] message = bytes(w[4]);
            byte[] sig = bytes(w[5]);
            String what = "PKCS #1 with " + w[1] + ", " + n.bitLength() + " bits";
            Check.isTrue(RsaVerify.pkcs1(n, e, h, message, sig), what + ": valid");
            Check.isFalse(RsaVerify.pkcs1(n, e, h, Bytes.concat(message, new byte[] { 0 }), sig), what + ": another message");
            Check.isFalse(RsaVerify.pkcs1(n, e, h == HashAlg.SHA256 ? HashAlg.SHA384 : HashAlg.SHA256, message, sig), what + ": another hash");
            byte[] flipped = sig.clone();
            flipped[sig.length / 2] ^= 4;
            Check.isFalse(RsaVerify.pkcs1(n, e, h, message, flipped), what + ": a flipped bit");
            Check.isFalse(RsaVerify.pss(n, e, h, message, sig, h.length()), what + ": not a PSS signature");
        }
    }

    /**
     * RSA-PSS signatures made by the reference verify for salt lengths of the hash length, zero and twenty; other salt lengths, hashes
     * and changed signatures do not.
     * <p>
     * 기준이 만든 RSA-PSS 서명이 salt 길이가 해시 길이, 0, 20 일 때 검증되고, 다른 salt 길이·해시와 바꾼 서명은 검증되지 않는다.
     */
    public void testRsaPss() {
        List<String[]> lines = VECTORS.all("rsa-pss");
        Check.isTrue(lines.size() >= 36, "enough PSS vectors");
        // 벡터마다 서명을 검증한다.
        for (int i = 0; i < lines.size(); i++) {
            String[] w = lines.get(i);
            HashAlg h = hash(w[1]);
            int salt = Integer.parseInt(w[2]);
            BigInteger n = new BigInteger(w[3], 16);
            BigInteger e = new BigInteger(w[4], 16);
            byte[] message = bytes(w[5]);
            byte[] sig = bytes(w[6]);
            String what = "PSS with " + w[1] + ", salt " + salt + ", " + n.bitLength() + " bits";
            Check.isTrue(RsaVerify.pss(n, e, h, message, sig, salt), what + ": valid");
            Check.isFalse(RsaVerify.pss(n, e, h, message, sig, salt + 1), what + ": another salt length");
            Check.isFalse(RsaVerify.pss(n, e, h, Bytes.concat(message, new byte[] { 0 }), sig, salt), what + ": another message");
            Check.isFalse(RsaVerify.pss(n, e, h == HashAlg.SHA256 ? HashAlg.SHA384 : HashAlg.SHA256, message, sig, salt), what + ": another hash");
            byte[] flipped = sig.clone();
            flipped[sig.length - 1] ^= 1;
            Check.isFalse(RsaVerify.pss(n, e, h, message, flipped, salt), what + ": a flipped bit");
            Check.isFalse(RsaVerify.pkcs1(n, e, h, message, sig), what + ": not a PKCS #1 signature");
        }
    }
}
